//
//  Fluid Simulation using Compute Shaders
//  Native Metal Shader - Advanced Physics
//

#include <metal_stdlib>
using namespace metal;

// MARK: - Structures

struct FluidCell {
    float density;
    float2 velocity;
    float pressure;
};

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float viscosity;
    float diffusion;
    float force_strength;
    float color_intensity;
    float buoyancy;          // upward force proportional to density
    float vorticity;         // vorticity confinement strength
    float dye_amount;        // per-frame dye injection amount
    float dissipation;       // global dissipation
    float noise_scale;       // curl-noise scale
    float noise_speed;       // curl-noise time speed
};

// MARK: - Compute Shader (Fluid Simulation)

kernel void fluid_advection(
    device FluidCell *state [[buffer(0)]],
    constant Uniforms &uniforms [[buffer(1)]],
    uint2 gid [[thread_position_in_grid]]
)
{
    uint width = uint(uniforms.OutputSize.x);
    uint height = uint(uniforms.OutputSize.y);

    if (gid.x >= width || gid.y >= height) return;

    uint idx = gid.y * width + gid.x;
    FluidCell cell = state[idx];

    float dt = 1.0 / 60.0;

    // Semi-Lagrangian advection
    float2 pos = float2(gid) - cell.velocity * dt;
    pos = clamp(pos, float2(0.0), float2(width - 1, height - 1));

    uint2 p0 = uint2(floor(pos));
    uint2 p1 = uint2(ceil(pos));
    float2 f = fract(pos);

    // Bilinear interpolation
    uint idx00 = p0.y * width + p0.x;
    uint idx10 = p0.y * width + p1.x;
    uint idx01 = p1.y * width + p0.x;
    uint idx11 = p1.y * width + p1.x;

    FluidCell c00 = state[idx00];
    FluidCell c10 = state[idx10];
    FluidCell c01 = state[idx01];
    FluidCell c11 = state[idx11];

    FluidCell result;
    result.density = mix(
        mix(c00.density, c10.density, f.x),
        mix(c01.density, c11.density, f.x),
        f.y
    );

    result.velocity = mix(
        mix(c00.velocity, c10.velocity, f.x),
        mix(c01.velocity, c11.velocity, f.x),
        f.y
    );

    // Apply diffusion
    result.density *= (1.0 - uniforms.diffusion * dt);
    result.velocity *= (1.0 - uniforms.viscosity * dt);

    state[idx] = result;
}

kernel void fluid_forces(
    device FluidCell *state [[buffer(0)]],
    constant Uniforms &uniforms [[buffer(1)]],
    uint2 gid [[thread_position_in_grid]]
)
{
    uint width = uint(uniforms.OutputSize.x);
    uint height = uint(uniforms.OutputSize.y);

    if (gid.x >= width || gid.y >= height) return;

    uint idx = gid.y * width + gid.x;
    FluidCell cell = state[idx];

    // Time
    float t = float(uniforms.FrameCount) * 0.016 * uniforms.noise_speed;

    // Simple curl-like force field using trigonometric noise (cheap)
    float2 p = (float2(gid) / float2(width, height)) * uniforms.noise_scale + float2(t, -t*0.7);
    float n1 = sin(6.28318*(p.x + 0.5*cos(2.0*p.y)));
    float n2 = cos(6.28318*(p.y + 0.5*sin(2.0*p.x)));
    float2 curlF = float2(n2, -n1);
    curlF *= uniforms.force_strength;

    // Buoyancy upward by density
    float2 buoy = float2(0.0, -uniforms.buoyancy * cell.density);

    // Apply forces
    cell.velocity += curlF + buoy;

    // Inject dye to make motion visible
    cell.density = clamp(cell.density + uniforms.dye_amount * 0.5, 0.0, 1.0);

    // Global dissipation
    cell.density *= max(0.0, 1.0 - uniforms.dissipation);
    cell.velocity *= max(0.0, 1.0 - uniforms.dissipation * 0.5);

    state[idx] = cell;
}

// MARK: - Vertex Shader

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// MARK: - Fragment Shader

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    device FluidCell *fluidState [[buffer(0)]],
    constant Uniforms &uniforms [[buffer(1)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    // Sample original image
    float4 color = sourceTexture.sample(textureSampler, in.texCoord);

    // Get fluid state at this position
    uint width = uint(uniforms.OutputSize.x);
    uint height = uint(uniforms.OutputSize.y);
    uint2 pos = uint2(in.texCoord * float2(width, height));
    uint idx = pos.y * width + pos.x;

    FluidCell cell = fluidState[idx];

    // Visualize fluid density with a heavenly palette
    float d = clamp(cell.density, 0.0, 1.0);
    float3 base = float3(0.15, 0.35, 0.9);
    float3 glow = float3(1.0, 0.9, 0.6);
    float3 fluidColor = mix(base, glow, pow(d, 0.6));

    // Mix with original image
    color.rgb = mix(color.rgb, fluidColor, d * uniforms.color_intensity);

    // Add velocity visualization
    float velocityMag = length(cell.velocity);
    color.rgb += float3(smoothstep(0.0, 2.0, velocityMag) * 0.2);

    return color;
}

